// tail keeps the last n bytes of s.
func tail(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[len(s)-n:]
}

// Grade checks what a grow left in dir. It runs go build, which is
// "compiled"; then copies the task's hidden tests in and runs go test, which
// is "passed". The returned output is the tail of whatever failed.
func Grade(t Task, dir string) (compiled, passed bool, output string, err error) {
	run := func(args ...string) (string, error) {
		cmd := exec.Command("go", args...)
		cmd.Dir = dir
		out, err := cmd.CombinedOutput()
		return string(out), err
	}
	if out, err := run("build", "./..."); err != nil {
		return false, false, tail(out, 2000), nil
	}
	compiled = true
	for _, f := range t.Hidden {
		data, err := os.ReadFile(filepath.Join(t.Dir, "hidden", f))
		if err != nil {
			return compiled, false, "", err
		}
		if err := os.WriteFile(filepath.Join(dir, t.Package, f), data, 0o644); err != nil {
			return compiled, false, "", err
		}
	}
	out, testErr := run("test", "-count=1", "./...")
	if testErr != nil {
		return compiled, false, tail(out, 2000), nil
	}
	return compiled, true, "", nil
}

// growPrompt is the same advisory text for every variant, so the variants
// differ only in the intent.
const growPrompt = "# Context

A small Go package. Standard library only (plus what the context files import). Write each target file in full, gofmt-clean, with a doc comment on every exported identifier.
"

// copyTree copies the directory src into dst.
func copyTree(src, dst string) error {
	return filepath.WalkDir(src, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(src, p)
		if err != nil {
			return err
		}
		target := filepath.Join(dst, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o755)
		}
		data, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		return os.WriteFile(target, data, 0o644)
	})
}

// Prepare writes the project for one sample into dir: a go.mod, the task's
// context files (in the directory named for the task's package), a copy of the generator packages, the grow prompt, and one
// open record whose intent is the variant's text and whose scope is the target
// files. The hidden tests are not written; Grade adds them after the grow.
func Prepare(t Task, v Variant, generators, dir string) error {
	intent, err := t.Intent(v)
	if err != nil {
		return err
	}
	if err := t.Isolated(); err != nil {
		return err
	}
	mod := fmt.Sprintf("module design/%s\n\ngo 1.25\n", t.ID)
	if err := os.WriteFile(filepath.Join(dir, "go.mod"), []byte(mod), 0o644); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Join(dir, t.Package), 0o755); err != nil {
		return err
	}
	for _, f := range t.Context {
		data, err := os.ReadFile(filepath.Join(t.Dir, "context", f))
		if err != nil {
			return err
		}
		if err := os.WriteFile(filepath.Join(dir, t.Package, f), data, 0o644); err != nil {
			return err
		}
	}
	if err := copyTree(generators, filepath.Join(dir, "generators")); err != nil {
		return fmt.Errorf("copy generators: %w", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "PROMPT.md"), []byte(growPrompt+"\nThe target files, as project paths:\n"+targetPaths(t)), 0o644); err != nil {
		return err
	}
	scope := make([]string, 0, len(t.Target))
	for _, f := range t.Target {
		scope = append(scope, t.Package+"/"+f)
	}
	rec := record{
		ID:            fmt.Sprintf("design-%s-%s", t.ID, v),
		Title:         fmt.Sprintf("design eval: %s (%s)", t.ID, v),
		Status:        "open",
		CreatedAt:     "2026-10-16",
		Author:        "eval@example.com",
		Intent:        intent,
		Constraints:   []string{},
		AffectedScope: scope,
		Forbidden:     []string{},
		Type:          "blueprint",
	}
	data, err := yaml.Marshal(rec)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Join(dir, "provenance"), 0o755); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dir, "provenance", rec.ID+".yml"), data, 0o644)
}

// targetPaths lists the task's target files as project paths, one per line.
func targetPaths(t Task) string {
	var b strings.Builder
	for _, f := range t.Target {
		b.WriteString(t.Package + "/" + f + "\n")
	}
	return b.String()
}

func TestPrepare(t *testing.T) {
	task, err := LoadTask(writeTask(t, t.TempDir(), "ok", validTask))
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	if err := Prepare(task, VariantSignatures, "../../generators", dir); err != nil {
		t.Fatal(err)
	}
	mod, err := os.ReadFile(filepath.Join(dir, "go.mod"))
	if err != nil || !strings.Contains(string(mod), "module design/ok") {
		t.Fatalf("go.mod = %q, %v", mod, err)
	}
	for _, f := range []string{"p/ctx.go", "PROMPT.md", "generators/go/sedum.yaml", "provenance/design-ok-signatures.yml"} {
		if _, err := os.Stat(filepath.Join(dir, f)); err != nil {
			t.Errorf("missing %s: %v", f, err)
		}
	}
	rec, err := os.ReadFile(filepath.Join(dir, "provenance", "design-ok-signatures.yml"))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"status: open", "intent: s", "- p/a.go"} {
		if !strings.Contains(string(rec), want) {
			t.Errorf("record lacks %q:\n%s", want, rec)
		}
	}
	prompt, err := os.ReadFile(filepath.Join(dir, "PROMPT.md"))
	if err != nil || !strings.Contains(string(prompt), "p/a.go") {
		t.Fatalf("PROMPT.md must list the target paths: %q, %v", prompt, err)
	}
	if _, err := os.Stat(filepath.Join(dir, "p", "a_test.go")); err == nil {
		t.Fatal("the hidden test must not be written before grading")
	}
	if err := Prepare(task, "nope", "../../generators", t.TempDir()); err == nil {
		t.Fatal("an unknown variant must be an error")
	}
}

